def P(t): return "".join(f"<p>{x.strip()}</p>" for x in t.split("||"))
INTRO = """A cool, clear morning around 40 turns into a sunny, dry afternoon near 68, and the warm spell runs into the low 70s through Saturday before Sunday&rsquo;s front and a sharp cool-down. At home, the City Council adopted Jonesboro&rsquo;s 20-year growth plan, police have moved into a new headquarters on Highland Drive, A-State has named an interim football coach, and low, drought-starved rivers greet Saturday&rsquo;s duck opener. Beyond, Mary Peltola&rsquo;s Alaska win gives Democrats 56 Senate seats, President Trump has landed in China ahead of Thursday&rsquo;s meeting with Xi and Putin, and Iranian drones struck at U.S. bases in Bahrain and Kuwait."""
body = []
body.append('<h1>The Morning Letter</h1><div class="sub">With the compliments of the Editor, to Jonesboro, Brookland &amp; neighbors</div>')
body.append('<div class="date">Wednesday, the Eighteenth of November, 2026</div><div class="orn">&#10086;</div>')
body.append(P('Good morning,'))
body.append(P(INTRO))
body.append('<h2>The Day Ahead</h2>')
body.append(hourly); body.append(grid)
body.append(P("""A cool, clear start, around 40 at first light and 42 by 6 o&rsquo;clock, gives way to a fine, dry day: about 52 by 9, 65 at noon and a high near 68 by mid-afternoon under a mostly sunny sky, with no chance of rain and only a light breeze. After the 4:53 sunset it eases to about 59 by suppertime and 53 by 9 o&rsquo;clock, and tonight bottoms out in the mid- to upper 40s, noticeably milder than the last few nights.||The warm spell builds from there: about 71 on Thursday and 72 on Friday, and still about 71 on Saturday with lows in the 50s. A front brings the week&rsquo;s only real rain chance, about one in four, on Sunday, then much cooler air arrives: highs near 55 on Monday and 51 on Tuesday, with Monday morning&rsquo;s low near 35. The ground is badly in need of more than that; the region has been in drought for well over a year."""))
body.append('<h2>The Almanac</h2>')
body.append(f'''<table class="alm"><tr><td>First light</td><td>{alm['first_light']}</td><td>Sunrise</td><td>{alm['sunrise']}</td></tr>
<tr><td>Solar noon</td><td>{alm['noon']}</td><td>Sunset</td><td>{alm['sunset']}</td></tr>
<tr><td>Last light</td><td>{alm['last_light']}</td><td>Length of day</td><td>{alm['day_length']}</td></tr>
<tr><td>Change from yesterday</td><td>{alm['change'].replace('-','&minus;')}</td><td>Moon</td><td>{alm['moon']}, {alm['illum']}% lit</td></tr></table>''')
body.append(P("""The moon is just past first quarter, a little more than half lit, riding high in the south at dusk and setting around midnight; it grows each evening toward the full Beaver Moon around the 24th, two days before Thanksgiving. The day has shrunk to 10 hours and 11 minutes, a minute and 34 seconds shorter than yesterday. With the moon down after midnight, the small hours are dark enough to catch a stray meteor from the Leonid shower, which peaks each year around the 17th and 18th; look east after 2 a.m., and expect a handful an hour rather than a storm.||In the country, the combines have gone quiet and the talk has turned to water. The rice and bean fields stand in stubble, the wheat that went in on the drier ground is showing a faint green wash where it caught any moisture at all, and the sloughs and brakes along the Cache sit low ahead of Saturday&rsquo;s duck opener. Pecans are falling in the old yard trees, and the mild days are good for gathering them before the crows and squirrels do. It is a fine week to set out garlic and pansies, rake the leaves onto the garden beds as a winter blanket, and give young trees and shrubs a deep soaking, since a dry plant goes into a hard freeze the worse for it."""))
body.append(P('<i>Weather lore, not a forecast:</i> the old saying holds that a warm November is the sign of a bad winter. This November is doing its part to test it, with the 70s on tap through Saturday.'))
body.append('<h2>Of Local Interest</h2>')
body.append('<h3>Council adopts Jonesboro&rsquo;s 20-year growth plan</h3>')
body.append(P("""The Jonesboro City Council on Tuesday night approved the city&rsquo;s new Comprehensive Growth Plan and Master Street Plan, which together will guide where and how the city grows over the next 20 years. The plans were drafted by DPZ Co-Design, a consulting firm the city hired, using answers from a community survey, and went first to the Metropolitan Area Planning Commission on Oct. 27. They call for building the city around community and neighborhood hubs, making it easier to get around on foot and by bicycle as well as by car, and adding green spaces and parks.||Before the meeting, the council&rsquo;s Public Safety Committee unanimously approved the city&rsquo;s application for a federal Bulletproof Vest Partnership grant, which repays up to half the cost of 57 ballistic vest packages for the Police Department, $129,070 in all. The council also gave a first reading to an ordinance granting a private club permit, which allows a restaurant to serve alcohol, to Delta Catfish Crawfish, Grill and Seafood on South Caraway Road; it returns for another reading at the next meeting."""))
body.append('<h3>A-State names an interim football coach and begins a national search</h3>')
body.append(P("""Arkansas State University confirmed Tuesday that Butch Jones will not return as head football coach, effective immediately, and named Jalen Ortiz, the associate head coach who coaches the cornerbacks, interim head coach for the last two games, beginning Saturday at Louisiana Tech. Ortiz joined the staff in 2025 after stops at Utah State, Nevada, Oregon and Wyoming; of his players he said, &ldquo;They got hit with some adversity.&rdquo;||Athletic director Chris Pezman thanked Jones for his &ldquo;many contributions&rdquo; and said the university will conduct a national search for the program&rsquo;s 32nd head coach. Jones, who called his time in Jonesboro &ldquo;an honor and privilege,&rdquo; leaves with a 30&ndash;43 record over six seasons, including three straight bowl trips from 2023 to 2025; this year&rsquo;s team is 4&ndash;6."""))
body.append('<h3>Police move into their new headquarters on Highland Drive</h3>')
body.append(P("""The Jonesboro Police Department cut the ribbon Tuesday on its new station at 1709 East Highland Drive, the former Shelter Insurance building, and officers are already working there. The city paid $2.75 million for the building and its contents and $250,000 for upgrades, about $3 million in all, against at least $7 million for a new building, city leaders said. It has just over 14,000 square feet, about 30 offices and 51 parking spaces, and houses administration, criminal investigations, records, community outreach and D.A.R.E.; patrol, warrants, evidence, training and other units stay in the Caraway Road building.||Police services had been scattered across five buildings since a structural problem closed the Justice Complex in the summer of 2025. Chief Rick Elliott said the department is now &ldquo;consolidated down to two buildings,&rdquo; adding, &ldquo;not the most ideal, but under the circumstances, we&rsquo;ll take it.&rdquo; A single station remains the goal, he said, but it is years away and depends on money."""))
body.append('<h3>Early voting set for the Dec. 1 runoffs</h3>')
body.append(P("""Voters in two Craighead County races return to the polls Tuesday, Dec. 1. In Jonesboro, City Council Ward 5, Position 1, is a runoff between incumbent L.J. Bryant, who drew 38 percent on Nov. 3, and Patti Lack, who drew 29 percent; in Lake City, the mayor&rsquo;s race is between Daniel Haynes (38 percent) and Jackie Davis (36 percent), after incumbent Mayor Cameron Tate finished third. Those percentages are from the unofficial first-round count.||Early voting runs Nov. 24, 25, 27 and 30, from 8 a.m. to 5 p.m., at the Craighead County Election Annex, 315 West Jefferson Avenue in Jonesboro, and the Lake City Eastern Annex. On Election Day polls are open 7:30 a.m. to 7:30 p.m.; Jonesboro voters go to Valley View Church of Christ on Southwest Drive, and Lake City voters to the Eastern Annex."""))
body.append('<h3>Dry rivers greet duck hunters ahead of Saturday&rsquo;s opener</h3>')
body.append(P("""Duck season opens Saturday, but some 15 months of drought have left rivers and wetlands across the region low; the Delta is about 20 inches behind on rain. The Cache River gauge near Sedgwick reads about 1.7 feet, 2.8 feet lower than six months ago, and there is no visible water in parts of the river at the Highway 228 bridge on the Lawrence&ndash;Greene county line. The Black River at Pocahontas is barely above gauge level, though still flowing.||Randy Zellers of the Arkansas Game and Fish Commission said fewer acres of rice, whose flooded fields once held water for ducks, make it worse, and the commission does not usually pump groundwater, which is reserved for cities and farms. Warm weather has also delayed the migration, and some ducks are flying past a dry Arkansas to Louisiana. &ldquo;The best that we can hope for is to get some rain, get some water on the landscape,&rdquo; he said; Sunday&rsquo;s modest rain chance is the only one in the forecast."""))
body.append('<h3>At the courthouse: fentanyl trafficking and bank fraud cases</h3>')
body.append(P("""District Judge David Boling found probable cause Monday in several felony cases; the charges are allegations, and each defendant is presumed innocent. Wayne Frank Zillmer, 56, of Jonesboro is charged with trafficking fentanyl and five other drug counts after police say they found 4,216 pills and 65 grams of powder that looked like Adderall but field-tested positive for fentanyl at a home 236 feet from a school; he is held on $100,000 cash-only bond, with the new charges set for Jan. 25.||John Joseph Dominy, 56, who police say has no ties to Arkansas and is wanted on a felony warrant in New York, faces 12 felony counts, including financial identity fraud, forgery and theft. Police say he used fake driver&rsquo;s licenses to pose as customers and withdraw cash and money orders at Arvest Bank and at Simmons Bank on Caraway Road. His bond is $200,000, with circuit court set for Dec. 16."""))
body.append('<h3>Red kettles and borrowed books</h3>')
body.append(P("""The Salvation Army&rsquo;s bell ringers are back, and its Jonesboro leaders have set a $100,000 goal for the Red Kettle Campaign, the organization&rsquo;s biggest fundraiser, which supports its shelter, community meals and food pantry. About 20 kettles are out in Jonesboro, Paragould, Pocahontas and Walnut Ridge, and volunteers can sign up online; those under 18 need an adult along. One volunteer, who got help with food, bills and housing after moving here last December, is ringing for a second year and called the Salvation Army &ldquo;the center hub of the community.&rdquo;||Meanwhile the Craighead County Jonesboro Public Library&rsquo;s running counter says the books and other items its patrons have borrowed so far this year would have cost $2,625,190.97 to buy. And at Jonesboro Kindergarten Center on Tuesday, nursing students from the Northeast Arkansas Career Technical Center held their fourth annual teddy bear clinic, checking the children&rsquo;s bears with stethoscopes and gloves so that a visit to the doctor seems less frightening."""))
body.append('<h3>Around town</h3>')
body.append(P("""<b>Today:</b> the Jonesboro High School coat drive continues through Friday, and A-State men&rsquo;s basketball hosts Arkansas&ndash;Pine Bluff at 7 p.m.||<b>Thursday and Friday:</b> Williams Baptist University students stage the one-act &ldquo;The Balcony Scene&rdquo; in Startup Chapel, Walnut Ridge, Thursday at 7:30 p.m. and Friday at 4 p.m.; admission $3. Friday is Fill the Food Bank day for the Food Bank of Northeast Arkansas, which has less than 30 days of food on hand.||<b>Saturday:</b> the Lindsay Ainsworth kidney-transplant benefit art fair at the Bradbury Art Museum; the Judd Hill winter farmers market, 9 a.m. to 2 p.m. on Aggie Road; and &ldquo;A Night of Bluegrass&rdquo; with the Williams Baptist Bluegrass Band and Strings of Green at 7 p.m. at the Rock N&rsquo; Roll Hwy. 67 Event Venue in Pocahontas ($19.95; college students $14.95; 12 and under free).||<b>Next week:</b> Jonesboro Public Schools are out Nov. 23&ndash;27. On Monday, KASU&rsquo;s holiday Bluegrass Monday features Williamson Branch, and the Quorum Court takes up the proposed $60.67 million 2027 county budget again. On Tuesday at 10:30 a.m., a ribbon cutting at Jonesboro Municipal Airport marks the finished runway work. Entries for the 79th Jonesboro Christmas Parade, &ldquo;The Night Before Christmas,&rdquo; are due by 5 p.m. Nov. 27 at jonesborochristmasparade.org; the parade rolls down Main Street at 7 p.m. Friday, Dec. 4. The first White River Christmas Market is Nov. 27&ndash;29 at Lyon College in Batesville."""))
body.append('<h3>Our Neighbors Farther Afield</h3>')
body.append(P("""<b>Marked Tree.</b> Poinsett County sheriff&rsquo;s deputies arrested a 19-year-old West Memphis man on Nov. 13 on a felony rape charge involving a child under 14 in Marked Tree, on a warrant issued Nov. 10. The charge is an allegation, and no bond or court date has been reported."""))
body.append('<div style="break-inside:avoid;page-break-inside:avoid"><h2>From the Police Reports</h2><p class="note">Jonesboro Police incident reports. Charges are allegations. No names are printed.</p>'+P("""Jonesboro police filed 42 incident reports covering Monday morning through early Tuesday, with 10 arrests or citations, three of them of juveniles. Monday&rsquo;s fatal motorcycle crash on Harrisburg Road near Gladiolus Drive, reported here yesterday, is among them; the report lists careless and prohibited driving, a test of the SUV driver showed no alcohol, and the crash remains under investigation.""")+'</div>')
body.append(P("""<b>Gunfire.</b> A follow-up report on the shooting off Links Circle early Monday, also noted yesterday, says a bullet broke a bedroom window and lodged in an inside wall of an apartment; no one was hurt, and police are investigating it as a felony terroristic act.||<b>Break-ins.</b> Between Sunday evening and Monday morning someone got into a North Main Street business downtown and took a bicycle, a motorcycle frame and four 22-inch chrome wheels with tires, worth about $3,000 (commercial burglary). At a trailer business on C W Post Road, thieves pulled up a fence over the weekend and hauled off about $1,500 in scrap metal and aluminum (breaking or entering, felony theft). A storage unit on East Whitman Street was found broken into, with about $1,300 in power tools gone.||<b>Fraud.</b> A resident in the Sage Meadows Boulevard area reported that stolen checking-account numbers were used to pay about $870 in bills online (financial identity fraud, a felony). Two residents on Harrisburg Road reported their credit and debit cards used without permission, and a Casey Springs Road resident reported $230 taken from a PayPal account.||<b>Threats and thefts.</b> Someone allegedly threatened to stab and shoot the owner of a shop on South Caraway Road Monday afternoon (first-degree terroristic threatening, a felony); no arrest is listed. Detectives are also working felony threat reports from North Mays Street and East Nettleton Avenue. Prescription medication pens worth about $300 were taken from an employee-lounge refrigerator at St. Bernards on East Matthews; groceries were shoplifted at the East Highland Walmart; and wheel caps were stolen from a pickup on Colony Drive.||<b>Hit-and-runs.</b> Six leaving-the-scene reports came in, including the East Highland Walmart lot, East Johnson Avenue at County Road 912, Aggie Road at Marion Berry Parkway, and near Bittle Street and East Nettleton, where the other driver was identified.||<b>Arrests.</b> Three people were arrested on warrants for unpaid fines; a driver stopped for speeding on Nettleton near Market Place was cited on two city warrants and for driving without a license; and single arrests were made for marijuana possession near Johnson and Main, public intoxication on Southwest Drive, and obstructing governmental operations during a probation search on Olive Street.||<b>Also reported.</b> Several battery, fighting and threat reports with juvenile suspects or victims, 72401 area; two juveniles cited for small amounts of marijuana, 72401 area; and a reported sexual assault Monday night, under investigation.||<b>A word to drivers:</b> six hit-and-runs in a single day is a lot. If someone hits your car and drives off, stay put, note the vehicle, its direction and any part of the plate, photograph the damage, and call police from the scene."""))
body.append('<div><p class="note" style="break-after:avoid">At the county jails</p>'+P("""The Craighead County jail roster listed 311 people held Wednesday morning, 21 of them booked in the previous 48 hours. Among those listed first, failure-to-appear warrants were the most common charge, followed by parole violations, with domestic battery and leaving the scene of an accident also among them; the highest bond shown was $20,000, on a second-degree battery charge alleging injury to an emergency medical worker. The Randolph County roster listed 63 people held, with three booked in the last 48 hours, two on bench warrants and one for hindering apprehension, and three released in that time.""")+'</div>')

body.append('<h2>From the State</h2>')
body.append('<h3>Bill would send $2 million a year to each of Arkansas&rsquo; 75 counties</h3>')
body.append(P("""State Sen. Bryan King, a Green Forest Republican, has filed Senate Bill 6 for the 2027 session to create a &ldquo;Bring It Home Fund&rdquo; for county governments. The first $150 million the state collects each fiscal year from its gross receipts tax, the state sales tax, would go into the fund, and once it reached that sum the state treasurer would send $2 million to each of the 75 counties, Craighead included. The bill calls this a reallocation of existing revenue, not a new tax.||Counties would have to spend at least three-quarters of their share on roads and other infrastructure, water and sewer projects, equipment, law enforcement or county debt; the rest could also go to fire departments, qualifying local nonprofits or community projects. That sales-tax money now goes to state agencies and programs under the Revenue Stabilization Law, and the bill does not say what would cover the $150 million they would lose. It carries an emergency clause and a July 1, 2027, effective date; the Legislature convenes Jan. 11."""))
body.append('<h3>House members choose their committees with a Medicaid fight ahead</h3>')
body.append(P("""Members of the Arkansas House met at the Capitol on Tuesday to choose their committee seats for the 2027 session, picking in order of seniority, and many of the most senior chose the committees expected to decide the future of ARHOME, the state&rsquo;s Medicaid expansion covering more than 200,000 low-income adults. Four of the 10 most senior picked the Public Health, Welfare and Labor Committee, and 12 of the top 30 chose Insurance and Commerce. Majority Leader Howard Beaty Jr., a Crossett Republican, said ARHOME legislation could go through either one. Some members also chose Insurance and Commerce to weigh in on the proposed repeal of the Generating Arkansas Jobs Act, the 2025 law letting utilities charge customers for new power plants while they are being built.||Federal officials have refused to extend the approval ARHOME runs under, which expires in July. Minority Leader Andrew Collins, a Democrat, said members want a hand in the Medicaid talks because of high health costs and trouble getting care. By House tradition, the newest member to draw the last seniority number, Republican Mike Bishop of Harrison, received a $1 coin. Two new lawmakers were sworn in this week: Kara Armas of Pea Ridge, a Republican filling a Benton County House seat until Jan. 11, when her husband, Brian Armas, begins the full term he won, and Sen. Harrell Wilson of Rison, a Republican representing southeast Arkansas through January 2029."""))
body.append('<h3>Some families must choose between two child care programs by July 1</h3>')
body.append(P("""The state Early Childhood Commission, a panel of child care providers and advocates that advises the state Office of Early Childhood, decided Tuesday that 243 Arkansas families now getting child care help from two programs at once must choose one by July 1. The families use Early Head Start, the federal program that usually covers infants and toddlers from morning to early afternoon, together with School Readiness Assistance, the state&rsquo;s child care aid for low-income families, which covers the later afternoon. Commissioners had considered a Jan. 1 deadline.||Office director Ashelyn Abney said the change should free money for a waiting list of more than 3,500 families, and that she hopes all 243 keep receiving care. Commissioners worried that families giving up one program will have to find care for the hours it covered. Abney said 20 child care centers have closed since October 2025. Gov. Sarah Huckabee Sanders has proposed $20 million a year for early childhood education in next year&rsquo;s budget, and the Legislature will decide how it is spent."""))
body.append('<h3>Four-day school weeks and lower grades</h3>')
body.append(P("""Nearly one in five Arkansas school districts now run some or all of their schools four days a week, and new figures show those districts are more likely than others to get low state grades. Of the 49 four-day districts, 3 received an A for 2025-26, 19 a B, 18 a C, 6 a D and 3 an F, so 18 percent landed at D or F, against about 10 percent of districts statewide; the grades rest mostly on ATLAS, the state&rsquo;s yearly test in math, science and English.||Education Secretary Jacob Oliva has urged the three F-rated four-day districts, Blevins, Prescott and Strong-Huttig, to return to five days, and Blevins&rsquo; superintendent says her district will ask the state for permission to do so. The department says research links four-day weeks to weaker results, though districts set their own calendars, and some have thrived: Norfork, in north Arkansas, rose from a C to an A on a four-day schedule, which its superintendent credits with better attendance and less teacher turnover."""))
body.append('<h3>In brief</h3>')
body.append(P("""Gov. Sanders, speaking Tuesday at the Heritage Foundation, the conservative research group in Washington, on a tour for her new book &ldquo;Unapologetic,&rdquo; said conservatives &ldquo;have not done a great job of telling our story&rdquo; and should show how their policies touch daily life, pointing to the state&rsquo;s school cellphone ban and the 2023 LEARNS Act. A prosecutor has ruled that a state trooper was justified in shooting Clay Gresham, 43, during a Nov. 11 chase on Arkansas 274 in Calhoun County; police said Gresham had fled a domestic violence call and fired at deputies and then at the trooper. And the Arkansas chapter of the American Academy of Pediatrics, after the country lost its measles-elimination status, warned that childhood vaccination rates in much of the state have fallen below the level needed to protect whole communities; Arkansas has reported no measles cases this year."""))

body.append('<h2>From the Nation</h2>')
body.append('<h3>Peltola wins in Alaska, giving Democrats 56 Senate seats</h3>')
body.append(P("""Democrat Mary Peltola, a former Alaska congresswoman, has unseated Republican Sen. Dan Sullivan; the Associated Press called the race Tuesday night, the last Senate contest of the Nov. 3 midterms. With about 99 percent of ballots counted she had about 50.1 percent, enough to win outright without Alaska&rsquo;s ranked-choice tally. The result is unofficial until certified, and Sullivan&rsquo;s campaign has said it will not comment until every ballot is counted. Peltola, who is Yup&rsquo;ik, will be the first Alaska Native in the Senate.||Her win gives Democrats a 56-44 majority when the new Congress meets in January. Democrats also won the House, where they are on track for more than 250 of 435 seats, and House Democrats meet today behind closed doors to choose their nominee for speaker. Rep. Hakeem Jeffries of New York, their leader in the minority since 2023, has no challenger; if the full House elects him on Jan. 3, he would be the first Black speaker."""))
body.append('<h3>Trump says the U.S. is &ldquo;looking into&rdquo; a report of Iranian attack planning</h3>')
body.append(P("""President Trump said Tuesday in Manila that his administration is &ldquo;looking into&rdquo; reports that Iran may be planning attacks in Washington, after CNN reported, citing seven officials, that U.S. intelligence shows Iran developing options to strike senior officials with a &ldquo;dirty bomb,&rdquo; an ordinary explosive packed with radioactive material, or a chemical weapon. The reporting describes planning, not an imminent attack, and rests on a single outlet; it has not been confirmed elsewhere. Trump warned Iran would &ldquo;pay a price the likes of which no country has ever paid&rdquo; if an attack occurred. A White House official said there are &ldquo;no credible threats to the homeland,&rdquo; and Iran called the report baseless.||Separately, a federal judge in Brooklyn sentenced Asif Merchant, a Pakistani man, to 27&frac12; years in prison. Prosecutors said he plotted on behalf of Iran&rsquo;s Revolutionary Guard, the elite branch of its military, to hire assassins to kill President Trump, Joe Biden and Nikki Haley; the &ldquo;hit men&rdquo; he paid were undercover FBI agents, and no attack took place."""))
body.append('<h3>Navy secretary nominee calls the Iran war &ldquo;a strain on our Navy&rdquo;</h3>')
body.append(P("""Hung Cao, the acting Navy secretary and President Trump&rsquo;s choice for the permanent job, a Vietnamese refugee who became a Navy special operations officer, told the Senate Armed Services Committee at his confirmation hearing Tuesday that the eight-month war with Iran is &ldquo;a strain on our Navy,&rdquo; though he argued it has &ldquo;set China back on their heels.&rdquo; He agreed with an estimate cited by Sen. Elizabeth Warren that the naval blockade of Iranian shipping costs about $32.5 million a day and acknowledged the Navy has used expired munitions after recertifying them.||Senators of both parties pressed him on long deployments, food shortages aboard ships such as the carrier Abraham Lincoln, and suicide attempts among sailors. Chairman Roger Wicker, a Mississippi Republican, supports him, but because Cao left active duty in 2021, Congress must waive a rule requiring service secretaries to be out of uniform for seven years."""))
body.append('<h3>Nvidia beats forecasts, and its board says Huang will not return</h3>')
body.append(P("""Nvidia, the world&rsquo;s leading maker of artificial-intelligence chips, reported $115.8 billion in quarterly revenue after the market closed Tuesday, more than double a year earlier and above Wall Street&rsquo;s estimates, and forecast about $130 billion for the current quarter, assuming no data-center chip sales to China; its shares rose nearly 5 percent in after-hours trading. Board Chairman Harvey Jones said the company does not intend to reinstate co-founder Jensen Huang, who resigned as chief executive last week after reports of extramarital affairs, including one with a woman suspected of spying for China. Huang has said he would be open to returning, and President Trump has said he would support it. The board has hired a search firm to find a permanent chief, and Huang is due to testify before three congressional committees Dec. 1."""))
body.append('<h3>New questions about the FAA&rsquo;s role in the El Dorado ground stop</h3>')
body.append(P("""New reports on last Friday&rsquo;s nationwide flight shutdown, traced to a router installed by the contractor L3Harris at a Federal Aviation Administration radio site in El Dorado, point to the agency&rsquo;s own oversight. Little Rock station KATV reported that internal FAA documents show a draft rule change letting upgrades like El Dorado&rsquo;s be approved automatically as &ldquo;maintenance notifications&rdquo; without the earlier review with airlines, and The Washington Post reported that an FAA official supervised the contractor and signed off on the work; each is a single report not yet confirmed elsewhere. Transportation Secretary Sean Duffy has blamed a faulty router or contractor error. Sen. Jack Reed, a Rhode Island Democrat, called for an independent inspector general investigation and public hearings."""))
body.append('<h3>In brief</h3>')
body.append(P("""A classified computer network used by the National Security Agency, the government&rsquo;s main electronic intelligence agency, went down Tuesday during what it called routine maintenance; Director of National Intelligence Jay Clayton said it was not a cyberattack, and officials see no link to the recent outages at the FAA, JPMorgan Chase and United Airlines. A strong Pacific storm, an &ldquo;atmospheric river&rdquo; of tropical moisture, is bringing up to 4 feet of snow to the Sierra Nevada of California and Nevada this week. And new federal rules for SNAP, the food-stamp program, now require adults up to age 65 to work, train or volunteer 80 hours a month to keep their benefits, under the tax-and-spending law signed last year."""))

body.append('<h2>From Abroad</h2>')
body.append('<h3>Trump lands in China, where Xi greets him on the runway</h3>')
body.append(P("""President Trump landed early Wednesday in Shenzhen, the southern Chinese technology hub hosting this year&rsquo;s Asia-Pacific Economic Cooperation summit, a yearly meeting of 21 Pacific Rim economies, and Chinese leader Xi Jinping met him at the foot of Air Force One, a rare gesture returning Trump&rsquo;s own airport welcome for Xi in September. Xi said he wants &ldquo;a constructive, strategic and stable relationship.&rdquo; Before Trump arrived, Xi held talks in Shenzhen with Russian President Vladimir Putin, their 50th meeting by Xi&rsquo;s count.||On Thursday the three leaders are scheduled to hold three-way talks on the Iran war, Russia&rsquo;s war in Ukraine and nuclear weapons, though China&rsquo;s foreign ministry has said not to expect concrete results; Trump and Xi will also meet separately, with Washington hoping to extend a trade truce past January. In Manila, Trump announced &ldquo;the biggest trade deal&rdquo; yet with the Philippines, but Philippine officials spoke only of &ldquo;an understanding&rdquo; and said nothing was signed."""))
body.append('<h3>Iran strikes at U.S. bases in Bahrain and Kuwait after a U.S. raid</h3>')
body.append(P("""Iran&rsquo;s Revolutionary Guard said Tuesday it launched drones at a U.S. radar at Sheikh Isa Air Base in Bahrain, home of the Navy&rsquo;s Fifth Fleet, the third such attack in five days. U.S. Central Command, which runs American forces in the Middle East, said the drones were shot down without damage, and U.S. forces then struck a Revolutionary Guard missile site on Qeshm Island in the Strait of Hormuz in what an official called self-defense. Early Wednesday Kuwait said its air defenses were fighting off &ldquo;hostile&rdquo; drones, which Iran said were aimed at Patriot missile batteries, and Bahrain intercepted another attack; no casualties were reported.||At sea, a ship of ADNOC, the United Arab Emirates&rsquo; national oil company, was struck in the strait overnight, leaving one crewman missing and 11 injured, according to a single report not yet confirmed elsewhere. Qatar, which carries messages between Washington and Tehran, warned that escalation poses an &ldquo;extremely grave danger&rdquo; to the chances of a deal, while President Trump says the U.S. blockade of Iran stays in place."""))
body.append('<h3>A Pentagon official&rsquo;s criticism of Ukraine&rsquo;s deep strikes angers allies</h3>')
body.append(P("""Elbridge Colby, the Pentagon&rsquo;s top policy official, told allies at NATO headquarters in Brussels on Tuesday that Ukraine&rsquo;s long-range strikes inside Russia have been a &ldquo;spectacle&rdquo; that has &ldquo;not been effective in driving an end to the war,&rdquo; though he credited its shorter-range drones with slowing Russian advances. German Defense Minister Boris Pistorius called criticizing strikes on Russian military targets &ldquo;quite a stupid thing,&rdquo; and Britain&rsquo;s defense secretary, Wes Streeting, said it is not Britain&rsquo;s place to tell Ukraine how to fight. The dispute follows this week&rsquo;s Ukrainian attack on the Kerch Bridge linking Russia to occupied Crimea, where Ukrainian officials say a road section collapsed; the Kremlin says the bridge &ldquo;will be restored.&rdquo;"""))
body.append('<h3>Saudi Arabia replaces its Yemen commander as the Houthis near Aden</h3>')
body.append(P("""Saudi King Salman has replaced the commander of the Saudi-led coalition fighting in Yemen after weeks of gains by the Houthis, the Iran-backed rebels who have held the capital, Sanaa, since 2014, handing command to Gen. Fayyad Al-Ruwaili, chief of the Saudi General Staff. A Yemeni security official said the rebels have reached the coast about 60 miles west of Aden, the southern port that serves as the seat of the internationally recognized government; the Houthis say they do not plan to attack the city, and analysts do not see an assault as imminent. The coalition said its strikes Tuesday hit 60 military targets, and on Wednesday Yemen&rsquo;s parliament voted to label the Houthis a terrorist group."""))
body.append('<h3>Netanyahu loses a fight over Israel&rsquo;s parliamentary speaker</h3>')
body.append(P("""Israel&rsquo;s parliament, the Knesset, elected Matan Kahana, a former special forces soldier allied with opposition leader Gadi Eisenkot, a former army chief of staff, as its speaker on Tuesday by 66 votes to 52, defeating the candidate of Prime Minister Benjamin Netanyahu&rsquo;s Likud party. The speaker controls the chamber&rsquo;s schedule and can speed or stall bills, including Netanyahu&rsquo;s changes to the courts. No camp won the 61 seats needed to govern in the Oct. 27 election, and Netanyahu leads a caretaker government while coalition talks go on; if no government forms, Israel faces another election early next year."""))
body.append('<h3>In brief</h3>')
body.append(P("""The United Nations climate summit, COP31, in Antalya, Turkey, enters its last days split over a draft deal due Friday, with the Arab Group and Russia rejecting language on moving away from fossil fuels and the European Union backing a goal of 35 percent electrification by 2035; any agreement needs the consent of nearly 200 countries. On Thursday the International Court of Justice, the U.N.&rsquo;s top court, is scheduled to rule on whether Myanmar committed genocide against the Rohingya, a mostly Muslim minority."""))

body.append('<div style="break-inside:avoid;page-break-inside:avoid"><h2>Markets &amp; the Farm</h2><p class="note">Figures are as of Tuesday&rsquo;s close, November 17. Week changes are measured from the close of Friday, November 13.</p><table class="mk"><tr><th>Index</th><th>Close</th><th>Day</th><th>Since Friday</th></tr><tr><td>S&amp;P 500</td><td class="n">7,340.53</td><td class="n">&minus;76.06 (&minus;1.03%)</td><td class="n">&minus;2.9%</td></tr><tr><td>Dow Jones Industrials</td><td class="n">50,759.42</td><td class="n">&minus;848.75 (&minus;1.64%)</td><td class="n">&minus;3.0%</td></tr><tr><td>Nasdaq Composite</td><td class="n">24,328.38</td><td class="n">&minus;181.37 (&minus;0.74%)</td><td class="n">&minus;3.2%</td></tr></table></div>')
body.append(P("""Stocks fell again on Tuesday, the S&amp;P 500&rsquo;s fourth straight loss, leaving it at its lowest close since late July; at its low the Dow was down more than 1,000 points. Chip stocks were sold ahead of Nvidia&rsquo;s report, Salesforce fell about 9 percent and UnitedHealth about 5 percent, and the string of technology outages added to the unease. Nvidia&rsquo;s strong results after the bell lifted its shares about 5 percent in late trading. Today brings the government&rsquo;s housing-starts report and earnings from Target, Lowe&rsquo;s and TJX; Walmart reports Thursday morning."""))
body.append('<h3>What analysts are saying</h3>')
body.append('<ul class="picks"><li><b>Analysts leaned toward buying: CSCO</b> (Cisco Systems, the maker of computer-networking equipment and security software). HSBC upgraded it to buy on Tuesday and raised its price target to $133 from $120, citing strong quarterly results, raised earnings guidance and an attractive valuation; DZ Bank also upgraded it. Risk: a broad sell-off in technology and AI spending, like Tuesday&rsquo;s, can drag the shares down regardless of the company&rsquo;s own results.</li><li><b>Analysts leaned toward buying: MDT</b> (Medtronic, the maker of heart, diabetes and surgical devices). Piper Sandler upgraded it to overweight, saying several new growth drivers should push sales above Wall Street&rsquo;s estimates. Risk: slow product launches would leave sales short of that forecast.</li><li><b>Analysts leaned toward buying: WMT</b> (Walmart, the Bentonville-based retailer and the nation&rsquo;s largest). Stifel restarted coverage at buy with a $145 target, expecting double-digit growth in earnings per share; this is a fresh start of coverage, not an upgrade. Risk: strained shoppers and tariff costs could squeeze its margins; it reports results Thursday.</li><li><b>Analysts turned cautious: PEP</b> (PepsiCo, the Frito-Lay snacks and Pepsi drinks company). Bernstein cut it to underperform and its target to $128, citing &ldquo;persistent pressure&rdquo; in North America, where it expects snack volumes to fall about 2 percent in 2027; the shares fell about 3 percent. Risk to the cautious view: overseas strength or cost cuts could beat that forecast.</li><li><b>Analysts turned cautious: TSN</b> (Tyson Foods of Springdale, the beef, chicken and pork processor). JPMorgan cut it to neutral from overweight, saying the stock already reflects the recovery in beef and steadier chicken results and that it is waiting for the business itself to improve. Risk to the cautious view: a faster beef recovery could lift profits.</li></ul>')
body.append('<p class="note">This is information about what analysts said, not advice to buy or sell.</p>')
body.append('<h3>Commodities</h3>')
body.append('<table class="mk split"><tr><th>Commodity</th><th>Close</th><th>Change</th></tr><tr><td>WTI crude (Dec.)</td><td class="n">$86.01</td><td class="n">+$0.29</td></tr><tr><td>Brent crude (Jan.)</td><td class="n">$93.14</td><td class="n">about +$0.71</td></tr><tr><td>Arkansas avg. regular gas (AAA, Nov. 12)</td><td class="n">$3.55</td><td class="n">&minus;16&cent; on week</td></tr><tr><td>Jonesboro metro avg. gas (AAA, Nov. 12)</td><td class="n">$3.48</td><td class="n">&minus;15&cent; on week</td></tr><tr><td>Live cattle (Dec.), per cwt</td><td class="n">$218.78</td><td class="n">&minus;$1.55</td></tr><tr><td>Feeder cattle (Jan.), per cwt</td><td class="n">$328.20</td><td class="n">&minus;$4.90</td></tr><tr><td>Lean hogs (Dec.), per cwt</td><td class="n">$53.10</td><td class="n">&minus;$2.25</td></tr><tr><td>Corn (Dec.), per bu.</td><td class="n">$4.46&frac34;</td><td class="n">&minus;2&cent;</td></tr><tr><td>Soybeans (Jan.), per bu.</td><td class="n">$12.25&frac12;</td><td class="n">&minus;3&frac12;&cent;</td></tr><tr><td>Wheat, Chicago (Dec.), per bu.</td><td class="n">$5.95&frac14;</td><td class="n">+8&frac14;&cent;</td></tr><tr><td>Rough rice (Jan.), per cwt</td><td class="n">$18.37</td><td class="n">+2&frac12;&cent;</td></tr><tr><td>Cotton (Dec.), per lb.</td><td class="n">77.32&cent;</td><td class="n">+0.32&cent;</td></tr></table>')
body.append('<p class="note">Oil was held up by renewed fighting around the Strait of Hormuz and held back by forecasts of an oversupplied market. Lean hogs touched a contract low during the day. Feeder cattle, rough rice and cotton: single source (Brownfield). Gasoline: AAA Arkansas, Nov. 12; the next release is due Thursday.</p>')

body.append('<h2>On the Field</h2>')
body.append(P("""<b>Arkansas State</b> football (4&ndash;6, 2&ndash;4 Sun Belt), under interim coach Jalen Ortiz after the change reported above, plays at Louisiana Tech (8&ndash;2), winner of seven straight, on Saturday at 6 p.m. in Ruston on ESPN+, and closes at home against Troy on Nov. 28; it needs both wins to become bowl-eligible."""))
body.append(P("""<b>A-State men&rsquo;s basketball</b> (2&ndash;2) hosts winless Arkansas&ndash;Pine Bluff (0&ndash;5) tonight at 7 at First National Bank Arena, on ESPN+, after Saturday&rsquo;s 99&ndash;65 win over Dillard. Next comes a Thanksgiving tournament in Miami, Nov. 23&ndash;25."""))
body.append(P("""<b>Arkansas</b> (4&ndash;6, 2&ndash;5 SEC), fresh off its 34&ndash;6 rout of South Carolina, plays at Texas, fifth in Tuesday&rsquo;s College Football Playoff rankings, on Saturday at 2:30 p.m. in Austin, on ABC or ESPN. The Razorbacks have not won in Austin since 2003 and must beat both Texas and LSU to reach a bowl."""))
body.append(P("""<b>Tennessee</b> (8&ndash;2, 5&ndash;2 SEC) slipped one spot to ninth in Tuesday night&rsquo;s playoff rankings despite its 22&ndash;7 win at Texas A&amp;M. The Vols host unranked LSU (6&ndash;4) on Senior Day, Saturday at 2:30 p.m. Central on ABC, with former Vols coach Lane Kiffin, now at LSU, returning to Knoxville. Receiver Mike Matthews is out for the season, and Josh Heupel has not named his starting quarterback."""))

body.append('<h2>Afield &amp; Afloat</h2>')
body.append('<p class="note">Ratings are rule-of-thumb estimates from the forecast, the rut calendar and the sun, not measurements of animal or fish behavior.</p>')
body.append('<h3>Deer outlook: Good</h3>')
body.append(P("""The rut is still in its peak window for north Arkansas, dawn is cool at about 38 to 40, the wind is light at about 6 mph, and the barometer, high at 30.38 inches, eases slowly through the day. Windows: about 6:12 to 8:40 a.m.; 10 a.m. to 2 p.m. is realistic with bucks cruising; and 2:53 p.m. to sunset at 4:53. <b>Tip:</b> with the afternoon climbing to the upper 60s, deer will bed in shade and on the cool north faces of the ridges by midday; hunt the morning hard and the last hour of light, and if you sit through midday, watch the thick edges between bedding cover and the nearest water, since dry woods send deer to drink."""))
body.append(P("""<b>Tomorrow, Thursday (estimate: Good).</b> A much milder dawn near 50, nearly calm winds and the rut still on, though the afternoon reaches about 70. Windows: about 6:13 to 8:43 a.m., 10 a.m. to 2 p.m., and 2:52 p.m. to sunset at 4:52. <b>Tomorrow&rsquo;s tip:</b> in still air your scent pools and drifts rather than carrying away, so play the thermals: sit low in the morning while the air sinks, then climb higher in the afternoon as it rises."""))
body.append('<h3>Fishing outlook: Good</h3>')
body.append(P("""A slow fall in pressure, an afternoon near 67 and a light chop make for a good day on Craighead Forest Lake and Lake Frierson. Best times: late morning through mid-afternoon as the sun warms the water, and the last hour before the 4:53 sunset. <b>Tip:</b> after the cold nights, the north banks that take the full afternoon sun warm first; work a small crankbait or a spinnerbait slowly along them for bass, and look for crappie suspended around brush piles and the fishing piers at 8 to 12 feet, where a small minnow under a slip cork does the work."""))
body.append(P("""<b>Tomorrow, Thursday (estimate: Good).</b> Steady pressure easing slightly, a warm afternoon near 70 and very light wind. Best times: late morning to mid-afternoon and the last hour before sunset. <b>Tomorrow&rsquo;s tip:</b> on a glassy, bright day the fish see you coming, so lengthen your casts, scale down to lighter line, and try bream and catfish around the deeper riprap with crickets or nightcrawlers."""))
body.append('<h3>In season now, and what is next (zones 3, 4, 6 and 8)</h3>')
body.append('<table class="mk"><tr><th>Zone</th><th>Archery</th><th>Youth gun</th><th>Modern gun</th><th>Muzzleloader</th></tr>\n<tr><td>3</td><td>open to Feb. 28</td><td>Jan. 2&ndash;3</td><td>open to Dec. 6; Dec. 26&ndash;28</td><td>Dec. 12&ndash;14</td></tr>\n<tr><td>4</td><td>open to Feb. 28</td><td>Jan. 2&ndash;3</td><td>open to Nov. 22; Dec. 26&ndash;28</td><td>no season</td></tr>\n<tr><td>6</td><td>open to Feb. 28</td><td>Jan. 2&ndash;3</td><td>open to Dec. 6; Dec. 26&ndash;28</td><td>Dec. 12&ndash;14</td></tr>\n<tr><td>8</td><td>open to Feb. 28</td><td>Jan. 2&ndash;3</td><td>open to Dec. 6; Dec. 26&ndash;28</td><td>Dec. 12&ndash;14</td></tr></table>')
body.append(P("""<b>Modern gun season is open</b> in all four zones, and hunters checked more than 37,000 deer statewide over the opening weekend, Nov. 14&ndash;15. Zone 4, which takes in Craighead County, closes Sunday, Nov. 22, so this is its last week until the Dec. 26&ndash;28 holiday hunt; Zones 3, 6 and 8 run to Dec. 6, with muzzleloaders there Dec. 12&ndash;14.||<b>Ducks open Saturday, Nov. 21,</b> with the first segment running through Nov. 29 (some AGFC mailers wrongly showed Dec. 1), then Dec. 10&ndash;23 and Dec. 26 to Jan. 31. Geese follow the same segments. With the rivers as low as reported above, scout your holes before you haul the decoys. Quail are open through Feb. 7, and squirrel and rabbit run through Feb. 28; check agfc.com for wildlife-management-area rules."""))

body.append('<h2>Postscript</h2>')
body.append('<p class="ps">&ldquo;The year that is drawing toward its close has been filled with the blessings of fruitful fields and healthful skies. To these bounties, which are so constantly enjoyed that we are prone to forget the source from which they come, others have been added&nbsp;.&nbsp;.&nbsp;.&rdquo;</p>')
body.append('<p class="ps">&mdash; Abraham Lincoln, Proclamation of Thanksgiving, October 3, 1863. Eight days before the holiday, and under one more week of open skies, the opening line of the proclamation that set our national Thanksgiving still reads true.</p>')
body.append('<p class="sign">Until tomorrow, with good wishes &mdash;<br><b>The Editor</b></p>')
body.append('<div class="foot">Compiled from many reports.</div>')


# Pastimes
import os, json as _json
fleet = _json.load(open('fleet.json')) if os.path.exists('fleet.json') else None
def fleet_svg(d):
    n=d['size']; cs=30; lab=18; W=lab+n*cs; H=lab+n*cs
    o=[f'<svg viewBox="0 0 {W} {H}" xmlns="http://www.w3.org/2000/svg" style="width:100%;height:auto;display:block;font-family:inherit">']
    for c in range(n): o.append(f'<text x="{lab+c*cs+cs/2}" y="12" text-anchor="middle" font-size="10" fill="#8a6a35">{chr(65+c)}</text>')
    for r in range(n):
        o.append(f'<text x="{lab/2}" y="{lab+r*cs+cs/2+4}" text-anchor="middle" font-size="10" fill="#4a3618">{r+1}</text>')
        for c in range(n):
            x=lab+c*cs;y=lab+r*cs
            o.append(f'<rect x="{x}" y="{y}" width="{cs}" height="{cs}" fill="none" stroke="#8a6a35" stroke-width="1"/><text x="{x+cs/2}" y="{y+cs/2+6}" text-anchor="middle" font-size="17" font-weight="bold" fill="#2b2118">{d["grid"][r][c]}</text>')
    o.append('</svg>'); return ''.join(o)
body.append('<div class="page pastimes"><h2>The Pastimes</h2>')
left='<div><h3>I. Mate in Two</h3>'+f'<div class="board">{past["chess_svg"]}</div>'+f'<p>{past["chess_prompt"]} White is shown with the lighter, outlined pieces; the board is oriented with White at the bottom.</p></div>'
if fleet:
    tot=sum(len(x['word']) for x in fleet['ships'])
    clues=''.join(f'<li><span class="bl">{" ".join("_" for _ in x["word"])}</span> ({len(x["word"])}) {x["hint"]}</li>' for x in fleet['ships'])
    right=('<div><h3>II. Word Fleet</h3>'+'<div style="width:84%">'+fleet_svg(fleet)+'</div>'+
      f'<ol class="clues fl">{clues}</ol>'
      f'<p class="note">Each clue is a definition. Find its word in the grid, across or down. Fire by putting a pencil dot on a letter: one dot is one shot. Check the answers below, then circle each right letter and cross out each wrong one. Your score is your number of dots. <b>Best possible score: {tot} shots.</b> My shots: ________</p></div>')
    sol_ii='II. '+', '.join(f"{x['word']} {chr(65+x['c'])}{x['r']+1} {'across' if x['dir']=='A' else 'down'}" for x in fleet['ships'])
else:
    right='<div><h3>II. The Four Houses</h3>'+f'<p>{past["logic_intro"]}</p><ol class="clues">'+''.join(f'<li>{c}</li>' for c in past['logic_clues'])+f'</ol><p>{past["logic_question"]}</p></div>'
    sol_ii='II. '+past['logic_answer']
body.append('<div class="two">'+left+right+'</div>')
if os.path.exists('comic/today.svg'):
    body.append('<h3 style="margin-top:2pt;margin-bottom:0">III. Sorry, Earth</h3><div class="comic" style="margin:1pt 0 0 0"><img src="comic/today.png" style="width:92%;display:block;margin:0 auto"></div>')
body.append('<div class="flip box"><b>Solutions printed upside down.</b><br>I. '+past['chess_solution']+'<br>'+sol_ii+'</div></div>')

html = f'<!doctype html><html><head><meta charset="utf-8"><title>The Morning Letter</title><style>{css}</style></head><body>'+'\n'.join(body)+'</body></html>'
open('letter.html','w').write(html)
print(len(html))

